import json,collections,hashlib,csv
from pathlib import Path
root=Path('.')
print('INVENTORY',json.dumps({d:dict(collections.Counter(p.suffix for p in Path(d).rglob('*') if p.is_file() and '__pycache__' not in p.parts)) for d in ['src','scripts','tests','configs','.claude/skills','.claude/hooks']},sort_keys=True))
for name in ['prediction_gate','clv_gate','degradation_pause']:
 p=root/'data/bets'/f'{name}.json'
 if p.exists():
  x=json.loads(p.read_text(encoding='utf-8')); markets=x.get('markets',{})
  print('GATE',name,json.dumps({'keys':list(x),'generated_at':x.get('generated_at'),'markets':len(markets),'allowed':sum(bool(v.get('allowed')) for v in markets.values() if isinstance(v,dict)),'reasons':dict(collections.Counter(v.get('reason','') for v in markets.values() if isinstance(v,dict)))},ensure_ascii=True))
for p in sorted(Path('configs').glob('*.yaml')):
 import yaml
 x=yaml.safe_load(p.read_text(encoding='utf-8'))
 def walk(v,prefix=''):
  if isinstance(v,dict):
   for k,z in v.items():
    if any(t in k for t in ['shadow','gate','revalidation_price']): print('CONFIG',p.name,prefix+k,z)
    elif isinstance(z,dict): walk(z,prefix+k+'.')
 walk(x)
for directory in ['data','logs']:
 print('FILE_META',directory,dict(collections.Counter(p.suffix for p in Path(directory).rglob('*') if p.is_file())))
for p in sorted(Path('logs').glob('*')):
 if p.is_file() and p.suffix in ['.json'] and p.stat().st_size<30000:
  try:
   x=json.loads(p.read_text(encoding='utf-8')); print('LOG_JSON',p.name,{k:v for k,v in x.items() if k in ['timestamp','generated_at','status','exit_code','stage','failed','started_at','finished_at']})
  except Exception: pass
print('TRACKED_ENV', __import__('subprocess').run(['git','ls-files','.env'],capture_output=True,text=True).stdout.strip()!='')
